INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 23, 'theory', 'Quiz: sharding');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 23, 0, 'Why does sharding by hash(key) mod N handle adding a shard badly?', '["The hash stops being uniform", "The indexes have to be rebuilt", "The remainder changes for almost all keys, so most of the data moves", "The number of shards cannot be changed"]', 2, 'Consistent hashing solves this: when a node is added, only a part of its neighbor''s keys (about 1/N) move to it, and the rest stay in place.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 23, 1, 'What is wrong with range sharding by an auto-increment id?', '["All new records land in the last shard, which is overloaded while the others sit idle", "Range queries cannot be run", "An index cannot be created", "The keys take up too much space"]', 0, 'A monotonic key creates a hot spot at the tail; a hash, a composite key, or splitting the range so that writes go to different shards helps.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 23, 2, 'What are virtual nodes for in consistent hashing?', '["To encrypt the data", "So a physical node takes several places on the ring and the load is spread more evenly", "To speed up the network", "To store copies of backups"]', 1, 'Several places on the ring smooth out random skew and, when a node fails, spread its load across many neighbors.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 23, 3, 'What makes a query without the shard key unpleasant?', '["It is impossible", "It bypasses the indexes", "It breaks replication", "It runs on all shards, and the response time is set by the slowest one"]', 3, 'Scatter-gather loads the whole system and amplifies latency tails; that is why the key is chosen based on the most frequent queries.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 23, 4, 'What is the main drawback of two-phase commit (2PC)?', '["It cannot be used with indexes", "If the coordinator crashes between the phases, the participants wait while holding locks", "It does not guarantee atomicity", "It works only on a single shard"]', 1, 'That is why distributed systems often use sagas: chains of local transactions with compensating actions.');
